package glitch

import data.glitch_lib

# Check for 0.0.0.0 CIDR or bind address
is_open_ip(node) {
    node.ir_type == "String"
    regex.match("^0\\.0\\.0\\.0(/0)?$", node.value)
}

# Check variable name indicates binding/listening address
is_bind_var_name(name) {
    lower_name := lower(name)
    contains(lower_name, "bind")
} else {
    lower_name := lower(name)
    contains(lower_name, "listen")
} else {
    lower_name := lower(name)
    contains(lower_name, "_ip")
} else {
    lower_name := lower(name)
    contains(lower_name, "address")
} else {
    lower_name := lower(name)
    regex.match("^(ip|host)$", lower_name)
}

# Check nested Hash values for open IP using walk
hash_contains_open_ip(hash_node) {
    hash_node.ir_type == "Hash"
    walk(hash_node, [_, val])
    val.ir_type == "String"
    is_open_ip(val)
}

# Check for open IP in direct variable values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if variable name suggests binding address
    is_bind_var_name(var.name)

    # Direct string value check
    is_open_ip(var.value)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Improper Access Control - Service bound to 0.0.0.0 allowing access from any IP address, potentially exposing the service to unauthorized access. (CWE-284)"
    }
}

# Check for open IP nested in Hash values (e.g., Chef options hash)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    var.value.ir_type == "Hash"
    hash_contains_open_ip(var.value)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Improper Access Control - Service configuration contains bind address 0.0.0.0 in nested structure, allowing access from any IP address. (CWE-284)"
    }
}

# Check for open IP in atomic unit attributes by name pattern
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_bind_var_name(attr.name)
    is_open_ip(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Improper Access Control - Service bound to 0.0.0.0 allowing access from any IP address, potentially exposing the service to unauthorized access. (CWE-284)"
    }
}

# Check for open IP nested in Hash in atomic unit attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.value.ir_type == "Hash"
    hash_contains_open_ip(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
